mapper.select:
SELECT yao.id, yao.order_no, yao.kdt_id, yao.root_kdt_id, yao.app_id, yao.buyer_id, yao.buyer_phone, yao.open_id, yao.shop_name, yao.shop_display_no, yao.sku_version_text, yao.sku_interval_text, yao.price, yao.status, yao.pay_time_at, yao.use_status, yao.used_mt_shop_id, COALESCE(ms.poi_name, ms.name) AS used_mt_shop_name, yao.used_right_code, yao.used_at, yao.used_by_username, yao.use_remark, yao.create_time, yao.update_time FROM yz_app_order yao LEFT JOIN mt_shop ms ON ms.id = yao.used_mt_shop_id WHERE 1 = 1
AND yao.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND yao.kdt_id = #{kdtId}
AND yao.shop_name LIKE CONCAT('%', #{shopName}, '%')
AND ( yao.buyer_phone LIKE CONCAT('%', #{buyerKeyword}, '%') OR yao.open_id LIKE CONCAT('%', #{buyerKeyword}, '%') OR CAST(yao.buyer_id AS CHAR) LIKE CONCAT('%', #{buyerKeyword}, '%') )
AND ( yao.sku_version_text LIKE CONCAT('%', #{skuKeyword}, '%') OR yao.sku_interval_text LIKE CONCAT('%', #{skuKeyword}, '%') )
AND yao.status = #{status}
AND yao.use_status = #{useStatus}
AND yao.pay_time_at >= #{payStartTime}
AND yao.pay_time_at <= #{payEndTime}
ORDER BY yao.pay_time_at DESC, yao.id DESC
